package com.findit.servlet;
import com.findit.dao.ItemDAO;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.SQLException;
@WebServlet("/claim") public class ClaimServlet extends HttpServlet {protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.sendRedirect(q.getContextPath()+"/login");return;}try{int id=Integer.parseInt(q.getParameter("itemId"));String a=q.getParameter("answer");if(a==null||a.trim().length()<5){p.sendRedirect(q.getContextPath()+"/items?error=claim");return;}boolean ok=new ItemDAO().claim(id,((Number)s.getAttribute("userId")).intValue(),a.trim());p.sendRedirect(q.getContextPath()+"/items?"+(ok?"claimed=1":"error=claim"));}catch(NumberFormatException|SQLException e){throw new ServletException(e);}}}
